for (const match of sharedTexts.matchAll(/\btx\(\s*'([^']*)'/g)) {
	if (!Object.hasOwn(germanTranslations, match[1])) {
		failures.push(`German translations are missing shared text ${match[1]}`)
	}
}
for (const match of sharedTexts.matchAll(/\bnx\(\s*'([^']*)'\s*,\s*'([^']*)'/g)) {
	const pluralKey = `_${match[1]}_::_${match[2]}_`
	if (!Object.hasOwn(germanTranslations, pluralKey)) {
		failures.push(`German translations are missing shared plural text ${pluralKey}`)
	}
}

const germanJsMatch = germanJsSource.match(/OC\.L10N\.register\(\s*"cobudget",\s*(\{[\s\S]*\}),\s*"nplurals/)
if (!germanJsMatch) {
	failures.push('German JavaScript translation catalog could not be parsed')
} else if (!isDeepStrictEqual(JSON.parse(germanJsMatch[1]), germanTranslations)) {
	failures.push('German JSON and JavaScript translation catalogs differ')
}

for (const hierarchyText of [
	'Main category',
	'Subcategory',
		'Parent category (optional)',
		'None – this is a main category',
		'This main category already has subcategories and therefore cannot become a subcategory.',
		'Total - {category}',
	'Main-category criteria include only payments booked directly to that category. Select subcategories separately.',
	'A category cannot be its own parent category.',
	'A main category with subcategories cannot become a subcategory.',
	'Parent category not found or not available in this context.',
	'Only a main category can be selected as parent category.',
	'Parent category and subcategory must have the same type.',
	'Category has subcategories and cannot be deleted.'
]) {
	if (!Object.hasOwn(germanTranslations, hierarchyText)) {
		failures.push(`German translations are missing category hierarchy text ${hierarchyText}`)
	}
}

