assertEqual(defaultHeaderVisibility.showMobile, true, 'Nextcloud header is shown on mobile by default')
const originalDocument = globalThis.document
const appliedHeaderClasses = new Map()
globalThis.document = {
	documentElement: {
		classList: {
			toggle: (className, force) => appliedHeaderClasses.set(className, force),
		},
	},
}
nextcloudHeaderModule.applyNextcloudHeaderVisibility({ showDesktop: false, showMobile: true })
assertEqual(appliedHeaderClasses.get(nextcloudHeaderModule.NEXTCLOUD_HEADER_DESKTOP_HIDDEN_CLASS), true, 'disabled desktop setting applies the desktop hidden class immediately')
assertEqual(appliedHeaderClasses.get(nextcloudHeaderModule.NEXTCLOUD_HEADER_MOBILE_HIDDEN_CLASS), false, 'enabled mobile setting removes the mobile hidden class immediately')
if (originalDocument === undefined) {
	delete globalThis.document
} else {
	globalThis.document = originalDocument
}

