// Exercise the actual route watcher: query-only changes preserve the editor.
{
 const body = app.match(/async \$route\(to, from\) \{([\s\S]*?)\n\t\t\}/)[1]
 const routeChanged = new Function('return async function(to, from) {' + body + '}')()
 let resets = 0
 const state = { showWorkspaceMenu: true, selectedEntryId: 42, entrySidebarCreatingNew: false, syncEntrySidebarForRoute: async () => { resets++ } }
 for (const path of ['/', '/payments', '/projects/2', '/projects/2/payments', '/annual-overview']) {
  await routeChanged.call(state, { path, query: { type: 'income', page: '2' } }, { path, query: {} })
  await routeChanged.call(state, { path, query: {} }, { path, query: { type: 'income' } })
 }
 assertEqual(resets, 0, 'Filtering, paging and resetting within a view leave the sidebar alone')
 assertEqual(state.selectedEntryId, 42, 'Filter changes preserve the edited payment identity')
 state.entrySidebarCreatingNew = true
 await routeChanged.call(state, { path: '/', query: { search: 'Rent' } }, { path: '/' })
 assertEqual(resets, 0, 'Filtering also preserves a new payment draft')
 await routeChanged.call(state, { path: '/projects/3' }, { path: '/projects/2' })
 await routeChanged.call(state, { path: '/settings' }, { path: '/' })
 assertEqual(resets, 2, 'Changing area or page still synchronizes the payment context')
 await routeChanged.call(state, { path: '/', query: { search: 'Rent' } }, { path: '/', query: {openPayment: '25', workspace: '8'} })
 assertEqual(resets, 2, 'Filtering after a payment link preserves the editor')
 await routeChanged.call(state, { path: '/', query: {openPayment: '26', workspace: '8'} }, { path: '/' })
 assertEqual(resets, 3, 'A new payment link opens its payment even within the same view')
}

