const revealSource = addEntryModal.slice(addEntryModal.indexOf('\t\tasync revealPlanningDetails('), addEntryModal.indexOf('\t\tareaChoiceStyle(option) {'))
const planningCalls = []
let reducePlanningMotion = false
const revealPlanningDetails = new Function('window', `return {${revealSource}}`)({
 getComputedStyle: () => ({ paddingTop: '20px' }),
 matchMedia: () => ({ matches: reducePlanningMotion }),
}).revealPlanningDetails
const planningContext = {
 isOpen: true, showRecurrenceDetails: true, $nextTick: async () => {},
 $refs: {
  recurrenceGroup: { getBoundingClientRect: () => ({ top: 600, bottom: 900 }) },
  modalBody: { scrollTop: 100, getBoundingClientRect: () => ({ top: 80, bottom: 700 }), scrollTo: options => planningCalls.push(options) },
 },
}
await revealPlanningDetails.call(planningContext, 'recurrenceGroup', true)
assertEqual(isDeepStrictEqual(planningCalls, [{ top: 320, behavior: 'smooth' }]), true, 'Details scroll just enough within the owning form without changing focus')
planningCalls.length = 0
await revealPlanningDetails.call(planningContext, 'recurrenceGroup', false)
assertEqual(planningCalls.length, 0, 'Switching off does not move the form')
reducePlanningMotion = true
await revealPlanningDetails.call(planningContext, 'recurrenceGroup', true)
assertEqual(planningCalls.at(-1).behavior, 'auto', 'Detail reveal respects reduced motion')
planningCalls.length = 0
planningContext.$nextTick = async () => { planningContext.isOpen = false }
await revealPlanningDetails.call(planningContext, 'recurrenceGroup', true)
assertEqual(planningCalls.length, 0, 'Closing the sidebar cancels pending detail scrolling')

