assertContains(projectCreate, '<template v-if="creatingProject" #icon><NcLoadingIcon', 'Project create button shows busy state')
assertContains(projectCreate, 'v-if="$enableSharedProjects"', 'Area creation hides member search when shared areas are disabled')
