assertContains(projectList, 'v-if="isSharedProject(project)" class="project-card-balance"', 'Area overview hides meaningless balances for personal areas')
assertContains(projectList, '$texts.areas.personalArea()', 'Area overview labels one-member areas as personal')
assertContains(projectList, 'project?.is_shared !== undefined', 'Area overview prefers the authoritative server-side shared flag')

assertContains(projectDetail, 'openProjectSettings()', 'Project detail opens a dedicated settings page')
assertContains(projectSettings, 'canAddProjectMembers() {\n\t\t\treturn !!this.project && this.$enableSharedProjects && this.canManageProject && !this.hasFormerMembers;', 'Project settings hides member add action when shared areas are disabled, user is not owner, or a former member is unresolved')
assertContains(projectSettings, 'canRemoveProjectMembers() {\n\t\t\treturn !!this.project && this.$enableSharedProjects && this.canManageProject;', 'Project settings hides member remove action when shared areas are disabled or user is not owner')
assertContains(projectSettings, 'v-else-if="member.id !== project.owner_id && canRemoveProjectMembers"', 'Project settings lets the owner remove a former non-owner after settlement')
assertContains(projectSettings, '$texts.areaSettings.resolveFormerMember()', 'Project settings explains how to resolve a former member without losing history')
assertContains(projectSettings, '<template #icon><DeleteIcon :size="20" /></template>', 'Project settings uses an icon action for member removal')
assertContains(projectSettings, "this.memberAddError = extractError(e, this.$texts.areaDetail.memberAddError(member.displayName || member.id))", 'Project settings shows member add errors')
assertContains(projectSettings, "this.memberError = extractError(e, this.$texts.areaDetail.memberRemoveError())", 'Project settings shows member remove errors')
assertContains(projectSettings, 'this.editProjectData.name.trim()', 'Project settings trims whitespace-only names')
assertContains(projectSettings, "@blur=\"updateProject('name')\"", 'Area name saves on blur')
assertContains(projectSettings, "return this.updateProject('color');", 'Area color saves on selection')
assertNotContains(projectSettings, 'project-save-button', 'Area identity has no separate save button')

const packageJson = JSON.parse(read('package.json'))
if (packageJson.scripts?.['test:frontend-smoke'] !== 'node tests/frontend-smoke.mjs && node tests/tooltip-visibility.mjs && node tests/dialog-focus.mjs && node tests/sidebar-transition.mjs && node tests/fetch-json.mjs && node tests/http-timezone.mjs && node tests/annual-chart.mjs && node tests/annual-overview.mjs && node tests/mobile-reports.mjs && node tests/localization.mjs && node tests/master-data.mjs && node tests/workspace-settings.mjs && node tests/settings-confirmation.mjs && node tests/admin-settings.mjs && node tests/settings-folders.mjs && node tests/settings-autosave.mjs && node tests/area-settings.mjs && node tests/entry-member-selection.mjs && node tests/recurring-payments.mjs && node tests/keyboard-shortcuts.mjs && node tests/entry-lookups.mjs && node tests/area-create.mjs && node tests/area-settlement.mjs && node tests/area-confirmations.mjs && node tests/budget-form.mjs && node tests/budget-overview.mjs && node tests/area-overview.mjs && node tests/area-detail.mjs && node tests/mobile-payment-rows.mjs && node tests/settlement-overview.mjs && node tests/entry-history.mjs && node tests/payment-deletion.mjs && node tests/payment-summary.mjs && node tests/payment-filters.mjs && node tests/title-navigation.mjs && node tests/icons.mjs && node tests/reminder-organizer.mjs') {
	failures.push('package.json is missing test:frontend-smoke script')
}
if (!/^\^7\./.test(packageJson.dependencies?.['@nextcloud/dialogs'] || '')) {
	failures.push('package.json must use the supported @nextcloud/dialogs 7.x line')
}
if (!/^\^3\./.test(packageJson.dependencies?.['@nextcloud/router'] || '')) {
	failures.push('package.json must use the current @nextcloud/router 3.x line')
}
if (!/^\^7\./.test(packageJson.devDependencies?.['@nextcloud/webpack-vue-config'] || '')) {
	failures.push('package.json must use the current @nextcloud/webpack-vue-config 7.x line')
}

if (failures.length > 0) {
	console.error('Frontend smoke checks failed:')
	for (const failure of failures) {
		console.error(`- ${failure}`)
	}
	process.exit(1)
}

